from common import *
def fmt(x):
 if pd.isna(x):return '—'
 if isinstance(x,(float,np.floating)):return f'{x:.5g}'
 return str(x)
def table(f,columns=None):
 if columns is not None:f=f[[c for c in columns if c in f]]
 if f.empty:return '（无可用记录；状态见对应 CSV。）'
 return f.map(fmt).to_markdown(index=False)
